CREATE TABLE carrier_tender_automation_configs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,max_attempts integer NOT NULL DEFAULT 3 CHECK(max_attempts BETWEEN 1 AND 20),auto_retender_on_rejection boolean NOT NULL DEFAULT true,auto_retender_on_expiry boolean NOT NULL DEFAULT true,escalation_minutes integer NOT NULL DEFAULT 30 CHECK(escalation_minutes BETWEEN 5 AND 1440),enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES users(id),UNIQUE(company_id));
ALTER TABLE carrier_tender_attempts ADD COLUMN initiation_source text NOT NULL DEFAULT 'manual' CHECK(initiation_source IN('manual','automatic')),ADD COLUMN trigger_attempt_id uuid REFERENCES carrier_tender_attempts(id) ON DELETE SET NULL,ADD COLUMN terminal_reason text;
CREATE VIEW carrier_tender_automation_status WITH(security_invoker=true) AS SELECT a.company_id,a.id assignment_id,o.order_no,o.warehouse_id,a.status,coalesce(max(t.attempt_number),0) attempts,coalesce(cfg.max_attempts,3) max_attempts,count(*)FILTER(WHERE t.status='submitted') open_attempts,max(t.response_due_at)FILTER(WHERE t.status='submitted') response_due_at,coalesce(bool_or(t.initiation_source='automatic'),false) used_automatic_fallback FROM order_carrier_assignments a JOIN sales_orders o ON o.id=a.order_id LEFT JOIN carrier_tender_attempts t ON t.assignment_id=a.id LEFT JOIN carrier_tender_automation_configs cfg ON cfg.company_id=a.company_id AND cfg.enabled GROUP BY a.company_id,a.id,o.order_no,o.warehouse_id,a.status,cfg.max_attempts;
ALTER TABLE carrier_tender_automation_configs ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_tender_automation_configs FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_carrier_tender_automation_configs ON carrier_tender_automation_configs USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE,DELETE ON carrier_tender_automation_configs TO stockflow_app;GRANT SELECT ON carrier_tender_automation_status TO stockflow_app;CREATE INDEX carrier_tender_automatic_queue_idx ON carrier_tender_attempts(company_id,status,response_due_at,attempt_number);CREATE INDEX carrier_tender_trigger_idx ON carrier_tender_attempts(trigger_attempt_id);
CREATE FUNCTION notify_carrier_tender_change() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE rec record;BEGIN IF TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status THEN FOR rec IN SELECT m.user_id FROM company_members m JOIN order_carrier_assignments a ON a.id=NEW.assignment_id JOIN sales_orders o ON o.id=a.order_id WHERE m.company_id=NEW.company_id AND m.role IN('owner','admin','manager') AND(m.role='owner' OR EXISTS(SELECT 1 FROM user_warehouse_assignments u WHERE u.company_id=NEW.company_id AND u.user_id=m.user_id AND u.warehouse_id=o.warehouse_id)) LOOP INSERT INTO carrier_sla_notifications(company_id,user_id,carrier_service_id,warehouse_id,event_key,title,message,link_path,entity_type,entity_id,priority) SELECT NEW.company_id,rec.user_id,NEW.carrier_service_id,o.warehouse_id,'carrier-tender:'||NEW.id||':'||NEW.status,'Carrier tender '||NEW.status,o.order_no||' carrier tender attempt '||NEW.attempt_number||' is '||NEW.status||'.','/app/carrier-tenders','carrier_assignment',NEW.assignment_id,CASE WHEN NEW.status IN('rejected','expired') THEN 'high' ELSE 'normal' END FROM order_carrier_assignments a JOIN sales_orders o ON o.id=a.order_id WHERE a.id=NEW.assignment_id ON CONFLICT DO NOTHING;END LOOP;END IF;RETURN NEW;END$$;CREATE TRIGGER carrier_tender_notification_trigger AFTER INSERT OR UPDATE OF status ON carrier_tender_attempts FOR EACH ROW EXECUTE FUNCTION notify_carrier_tender_change();
